#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>
#include <string.h>

static long gcd_long(long a, long b)
{
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static long abs_long(long v)
{
    return v < 0 ? -v : v;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *end1 = NULL;
    errno = 0;
    long a = strtol(argv[1], &end1, 10);
    if (end1 == argv[1] || *end1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (a == LONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    char *end2 = NULL;
    errno = 0;
    long b = strtol(argv[2], &end2, 10);
    if (end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (b == LONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    if (llabs(a) > 1000000L || llabs(b) > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long abs_a = abs_long(a);
    long abs_b = abs_long(b);

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long g = gcd_long(abs_a, abs_b);
    long l;
    if (g == 0) {
        l = 0;
    } else {
        l = (abs_a / g) * abs_b;
    }

    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
